import dayjs from 'dayjs';
import utc from 'dayjs/plugin/utc';
import timezone from 'dayjs/plugin/timezone';

dayjs.extend(utc);
dayjs.extend(timezone);

export const processFlightData = async (from, to, date, apiKey) => {
  try {
    const response = await fetch('https://backend-284998006367.us-central1.run.app/api/flight-details', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${apiKey}`
      },
      body: JSON.stringify({
        from,
        to,
        date
      })
    });

    if (!response.ok) {
      throw new Error('Failed to fetch flight details');
    }

    const data = await response.json();
    return formatFlightData(data, from, to);
  } catch (error) {
    console.error('Error fetching flight details:', error);
    return [];
  }
};

export const formatFlightData = (data, from, to) => {
  if (!data || !Array.isArray(data)) return [];

  return data.map((flight, index) => ({
    key: `${from}-${to}-${index}`,
    from,
    to,
    flightNumber: flight.flightNumber,
    departureTime: formatTime(flight.departureTime),
    arrivalTime: formatTime(flight.arrivalTime),
    duration: formatDuration(flight.duration),
    aircraft: flight.aircraft,
    price: formatPrice(flight.price),
    seats: formatSeats(flight.availableSeats),
    airline: flight.airline
  }));
};

export const formatTime = (timeString) => {
  if (!timeString) return '';
  return dayjs(timeString).format('HH:mm');
};

export const formatDuration = (minutes) => {
  if (!minutes) return '';
  const hours = Math.floor(minutes / 60);
  const mins = minutes % 60;
  return `${hours}h ${mins}m`;
};

export const formatPrice = (price) => {
  if (!price) return '';
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD'
  }).format(price);
};

export const formatSeats = (seats) => {
  if (!seats) return 'N/A';
  return seats.toString();
};

/**
 * Enrich flight data with raw API information
 */
export const getEnrichedFlightData = (routeCode, classCode, dateString, classData, rawDataArray) => {
  const flights = classData[`${classCode}Flights`] || [];

  // Ensure raw data is available for each flight
  return flights.map(flight => {
    // If rawData is already present, just return the flight
    if (flight.rawData) return flight;

    try {
      // Find matching raw flight data
      const [origin, destination] = routeCode.split('-');

      const raw = rawDataArray.find(rawFlight => {
        return (
          (rawFlight.ID === flight.id || !flight.id) &&
          rawFlight.date === dateString &&
          rawFlight.originAirport === origin && 
          rawFlight.destinationAirport === destination &&
          rawFlight[`${classCode}Available`]
        );
      });

      // Return flight with raw data attached
      return {
        ...flight,
        rawData: raw || null
      };
    } catch (error) {
      console.warn('Error finding raw flight data:', error);
      return flight;
    }
  });
};

/**
 * Filter flights based on multiple criteria
 */
export const filterFlights = (flights, filters) => {
  const {
    segmentFilter,
    directFilter,
    sourceFilter,
    airlinesFilter,
    pointsFilter,
    segmentFilters,
    groupFilters
  } = filters;

  return flights.filter(flight => {
    // Skip if no raw data
    if (!flight.rawData) return false;

    // Check direct filter
    if (directFilter && !flight.direct) return false;

    // Check sources filter
    if (sourceFilter?.sources?.length > 0) {
      const source = flight.source || (flight.rawData && flight.rawData.source);

      if (sourceFilter.mode === 'include') {
        if (!sourceFilter.sources.includes(source)) return false;
      } else if (sourceFilter.mode === 'exclude') {
        if (sourceFilter.sources.includes(source)) return false;
      }
    }

    // Check airlines filter
    if (airlinesFilter?.airlines?.length > 0 && flight.airlines) {
      const flightAirlines = Array.isArray(flight.airlines) 
        ? flight.airlines 
        : flight.airlines.split(',').map(a => a.trim());

      const hasMatchingAirline = flightAirlines.some(airline => 
        airlinesFilter.airlines.includes(airline)
      );

      if (airlinesFilter.mode === 'include' && !hasMatchingAirline) return false;
      if (airlinesFilter.mode === 'exclude' && hasMatchingAirline) return false;
    }

    // Check points filter
    if (pointsFilter) {
      const points = parseInt(flight.miles || flight.points || flight.rawData?.MileageCost || 0, 10);

      if (isNaN(points)) return false;
      if (points < pointsFilter[0] || points > pointsFilter[1]) return false;
    }

    // Pass all filters
    return true;
  });
};

/**
 * Get unique segments from flight data
 */
export const getUniqueSegments = (flightData) => {
  if (!flightData || !flightData.routes) return [];

  const segments = new Set();

  // Extract all route segments
  Object.keys(flightData.routes).forEach(route => {
    const [origin, destination] = route.split('-');
    segments.add(`${origin}-${destination}`);
  });

  return Array.from(segments);
};

/**
 * Get unique sources from flight data
 */
export const getUniqueSources = (flightData) => {
  if (!flightData || !flightData.rawData) return [];

  const sources = new Set();

  // Extract all sources
  flightData.rawData.forEach(flight => {
    if (flight.source) {
      sources.add(flight.source);
    }
  });

  return Array.from(sources);
};

/**
 * Get unique airlines from flight data
 */
export const getUniqueAirlines = (flightData) => {
  if (!flightData || !flightData.rawData) return [];

  const airlines = new Set();

  // Extract all airlines from each class
  flightData.rawData.forEach(flight => {
    ['Y', 'W', 'J', 'F'].forEach(classCode => {
      const airlinesField = `${classCode}Airlines`;

      if (flight[airlinesField]) {
        flight[airlinesField].split(',').forEach(airline => {
          const trimmedAirline = airline.trim();
          if (trimmedAirline) {
            airlines.add(trimmedAirline);
          }
        });
      }
    });
  });

  return Array.from(airlines);
};

/**
 * Get points range from flight data
 */
export const getPointsRange = (flightData) => {
  if (!flightData || !flightData.rawData) return [0, 1000000];

  let min = Number.MAX_SAFE_INTEGER;
  let max = 0;

  // Find min and max points/miles across all flights and classes
  flightData.rawData.forEach(flight => {
    ['Y', 'W', 'J', 'F'].forEach(classCode => {
      const mileageField = `${classCode}MileageCost`;

      if (flight[mileageField]) {
        const miles = parseInt(flight[mileageField], 10);
        if (!isNaN(miles)) {
          min = Math.min(min, miles);
          max = Math.max(max, miles);
        }
      }
    });
  });

  // Return reasonable defaults if no data found
  if (min === Number.MAX_SAFE_INTEGER) return [0, 1000000];

  return [min, max];
};

/**
 * Get unique dates from flight data
 */
export const getUniqueDates = (flightData) => {
  if (!flightData || !flightData.rawData) return [];

  const dates = new Set();

  // Extract all dates
  flightData.rawData.forEach(flight => {
    if (flight.date) {
      dates.add(flight.date);
    }
  });

  return Array.from(dates).sort();
};
